//! A small systems tool that talks to the platform C library.
//!
//! It demonstrates:
//!   * declaring and calling native C functions via `extern "C"`,
//!   * using OS-level C types from the `libc` crate (`pid_t`, `uid_t`,
//!     `utsname`, `c_int`, ...),
//!   * converting safely between Rust strings and NUL-terminated C strings,
//!   * translating C error codes into `std::io::Error`.

use std::ffi::{CStr, CString};
use std::io;
use std::mem::MaybeUninit;
use std::os::raw::c_int;
use std::ptr;

// Functions from the C standard library / libc. The `libc` crate already
// declares most of these; we redeclare a few to show the raw FFI surface.
unsafe extern "C" {
    fn getpid() -> libc::pid_t;
    fn getuid() -> libc::uid_t;
    fn uname(buf: *mut libc::utsname) -> c_int;
    fn gethostname(name: *mut libc::c_char, len: libc::size_t) -> c_int;
}

// A function from a *separate* native C library (libm), linked in build.rs.
extern "C" {
    fn cbrt(x: libc::c_double) -> libc::c_double;
}
```

